import base64
import io
from PIL import Image # Pillowライブラリが必要です

# ここに、現在コードに貼り付けている Base64文字列 を入れてください
BASE64_STRING = ""

try:
    # 1. Base64デコード
    image_data = base64.b64decode(BASE64_STRING)
    
    # 2. メモリ上で画像として開いてみる
    image = Image.open(io.BytesIO(image_data))
    
    # 3. 情報表示
    print("✅ 成功: 有効な画像データです！")
    print(f"   - フォーマット: {image.format}")
    print(f"   - サイズ: {image.size} (幅 x 高さ)")
    print(f"   - モード: {image.mode}")
    
except Exception as e:
    print("❌ 失敗: 画像データとして認識できませんでした。")
    print(f"   - エラー詳細: {e}")
    print("\n💡 ヒント: 文字列の長さが足りない可能性があります。もう一度コピーし直してください。")